data_source.query:
FROM logs-openai.*
| WHERE data_stream.dataset IN ("openai.rate_limits", "openai.completions", "openai.embeddings", "openai.moderations", "openai.audio_speeches", "openai.audio_transcriptions", "openai.images")
| EVAL project_id = COALESCE(openai.rate_limits.project_id, openai.base.project_id)
// Normalize dated model snapshots (e.g. gpt-image-1-2025-04-23, omni-moderation-2024-09-26)
// to their base family by stripping a trailing -YYYY-MM-DD. OpenAI's usage API reports per
// dated snapshot, while rate_limits often lists only the base name, so without this the usage
// row finds no matching limit and is dropped from the headroom join.
| EVAL model = REPLACE(COALESCE(openai.rate_limits.model, openai.base.model), "-[0-9]{4}-[0-9]{2}-[0-9]{2}$", "")
// Every usage stream carries num_model_requests (RPM), but only completions/embeddings/moderations
// carry tokens and only the images stream carries an image count. usage_tokens and usage_images are
// normalized and COALESCEd to 0, so each stream contributes only to the dimensions it reports without
// inflating the others, and the panel still resolves when a usage stream has no data.
| EVAL usage_tokens = COALESCE(openai.base.usage_tokens, 0)
| EVAL usage_images = COALESCE(openai.base.usage_images, 0)
| STATS
    tpm_used_minute = SUM(usage_tokens),
    rpm_used_minute = SUM(openai.base.num_model_requests),
    ipm_used_minute = SUM(usage_images),
    tpm_limit = MAX(openai.rate_limits.max_tokens_per_1_minute),
    rpm_limit = MAX(openai.rate_limits.max_requests_per_1_minute),
    ipm_limit = MAX(openai.rate_limits.max_images_per_1_minute)
  BY project_id, model, minute = BUCKET(@timestamp, 1 minute)
| STATS
    tpm_used = MAX(tpm_used_minute), rpm_used = MAX(rpm_used_minute), ipm_used = MAX(ipm_used_minute),
    tpm_limit = MAX(tpm_limit), rpm_limit = MAX(rpm_limit), ipm_limit = MAX(ipm_limit)
  BY project_id, model
| WHERE tpm_limit IS NOT NULL OR rpm_limit IS NOT NULL OR ipm_limit IS NOT NULL
// TO_DOUBLE avoids integer division (otherwise utilization is always 0 until usage exceeds the limit)
| EVAL tpm_utilization = CASE(tpm_limit > 0, TO_DOUBLE(tpm_used) / tpm_limit, null)
| EVAL rpm_utilization = CASE(rpm_limit > 0, TO_DOUBLE(rpm_used) / rpm_limit, null)
| EVAL ipm_utilization = CASE(ipm_limit > 0, TO_DOUBLE(ipm_used) / ipm_limit, null)
// Push models with no usage (infinite headroom, not actionable) to the bottom,
// then rank by TPM utilization first (the dimension the headroom alert tracks),
// with RPM and image utilization, then absolute tokens, as tie-breakers.
| EVAL has_usage = CASE(COALESCE(tpm_used, 0) > 0 OR COALESCE(rpm_used, 0) > 0 OR COALESCE(ipm_used, 0) > 0, 1, 0)
| SORT has_usage DESC, COALESCE(tpm_utilization, -1) DESC, COALESCE(rpm_utilization, -1) DESC, COALESCE(ipm_utilization, -1) DESC, tpm_used DESC
| KEEP project_id, model, rpm_used, rpm_limit, rpm_utilization, tpm_used, tpm_limit, tpm_utilization, ipm_used, ipm_limit, ipm_utilization
| LIMIT 100

FROM logs-openai.*
| WHERE data_stream.dataset IN ("openai.rate_limits", "openai.completions", "openai.embeddings", "openai.moderations", "openai.audio_speeches", "openai.audio_transcriptions", "openai.images")
| EVAL project_id = COALESCE(openai.rate_limits.project_id, openai.base.project_id)
// Normalize dated model snapshots (e.g. gpt-image-1-2025-04-23, omni-moderation-2024-09-26)
// to their base family by stripping a trailing -YYYY-MM-DD. OpenAI's usage API reports per
// dated snapshot, while rate_limits often lists only the base name, so without this the usage
// row finds no matching limit and is dropped from the headroom join.
| EVAL model = REPLACE(COALESCE(openai.rate_limits.model, openai.base.model), "-[0-9]{4}-[0-9]{2}-[0-9]{2}$", "")
// Org-wide rollup by model across projects. Limits are first stabilized per project/model as the
// MAX snapshot over the look-back window, then summed across projects into a synthetic aggregate
// capacity -- stabilizing before the cross-project sum keeps the denominator independent of which
// minute each project's rate_limits snapshot happened to land in. Usage is each project's peak
// minute, summed across projects. This is NOT a real org throttle boundary (OpenAI enforces limits
// per project), so the aggregate utilization here is indicative, not an exact throttle distance.
| EVAL usage_tokens = COALESCE(openai.base.usage_tokens, 0)
| EVAL usage_images = COALESCE(openai.base.usage_images, 0)
| STATS
    tpm_used_minute = SUM(usage_tokens),
    rpm_used_minute = SUM(openai.base.num_model_requests),
    ipm_used_minute = SUM(usage_images),
    tpm_limit = MAX(openai.rate_limits.max_tokens_per_1_minute),
    rpm_limit = MAX(openai.rate_limits.max_requests_per_1_minute),
    ipm_limit = MAX(openai.rate_limits.max_images_per_1_minute)
  BY project_id, model, minute = BUCKET(@timestamp, 1 minute)
| STATS
    tpm_used = MAX(tpm_used_minute), rpm_used = MAX(rpm_used_minute), ipm_used = MAX(ipm_used_minute),
    tpm_limit = MAX(tpm_limit), rpm_limit = MAX(rpm_limit), ipm_limit = MAX(ipm_limit)
  BY project_id, model
| STATS
    tpm_used = SUM(tpm_used), rpm_used = SUM(rpm_used), ipm_used = SUM(ipm_used),
    tpm_limit = SUM(tpm_limit), rpm_limit = SUM(rpm_limit), ipm_limit = SUM(ipm_limit)
  BY model
| WHERE tpm_limit IS NOT NULL OR rpm_limit IS NOT NULL OR ipm_limit IS NOT NULL
// TO_DOUBLE avoids integer division (otherwise utilization is always 0 until usage exceeds the limit)
| EVAL tpm_utilization = CASE(tpm_limit > 0, TO_DOUBLE(tpm_used) / tpm_limit, null)
| EVAL rpm_utilization = CASE(rpm_limit > 0, TO_DOUBLE(rpm_used) / rpm_limit, null)
| EVAL ipm_utilization = CASE(ipm_limit > 0, TO_DOUBLE(ipm_used) / ipm_limit, null)
// Push models with no usage (infinite headroom, not actionable) to the bottom,
// then rank by TPM utilization first (the dimension the headroom alert tracks),
// with RPM and image utilization, then absolute tokens, as tie-breakers.
| EVAL has_usage = CASE(COALESCE(tpm_used, 0) > 0 OR COALESCE(rpm_used, 0) > 0 OR COALESCE(ipm_used, 0) > 0, 1, 0)
| SORT has_usage DESC, COALESCE(tpm_utilization, -1) DESC, COALESCE(rpm_utilization, -1) DESC, COALESCE(ipm_utilization, -1) DESC, tpm_used DESC
| KEEP model, rpm_used, rpm_limit, rpm_utilization, tpm_used, tpm_limit, tpm_utilization, ipm_used, ipm_limit, ipm_utilization
| LIMIT 100
